		printf("Error mapping file %s\n", argv[1]);
		exit(1);
	}

	res = write(fd, "1234567890", 10);
	if (res < 0) {
		printf("Error writing to file %s\n", argv[1]);
		exit(1);
	}

	munmap(buf, BUF_SIZE);
	close(fd);

	return 0;
}
