package com.example.demo.controller;

import com.example.demo.model.Question;
import com.example.demo.model.QuestionResponse;
import com.example.demo.service.QuestionService;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

import java.util.List;

@RestController
@RequestMapping("/api/question")
public class QuestionController {

    @Autowired
    private QuestionService questionService;

    @GetMapping("/{id}")
    public ResponseEntity<Question> getQuestion(@PathVariable("id") Long id) {
        Question question = questionService.getQuestion(id);
        return new ResponseEntity<>(question, HttpStatus.OK);
    }

    @GetMapping("/all")
    public ResponseEntity<List<Question>> getAllQuestions() {
        List<Question> questions = questionService.getAllQuestions();
        return new ResponseEntity<>(questions, HttpStatus.OK);
    }

    @PostMapping("/create")
    public ResponseEntity<QuestionResponse> createQuestion(@RequestBody Question question) {
        QuestionResponse questionResponse = questionService.createQuestion(question);
        return new ResponseEntity<>(questionResponse, HttpStatus.OK);
    }

    @PutMapping("/update")
    public ResponseEntity<QuestionResponse> updateQuestion(@RequestBody Question question) {
        QuestionResponse questionResponse = questionService.updateQuestion(question);
        return new ResponseEntity<>(questionResponse, HttpStatus.OK);
    }

    @DeleteMapping("/delete/{id}")
    public ResponseEntity<QuestionResponse> deleteQuestion(@PathVariable("id") Long id) {
        QuestionResponse questionResponse = questionService.deleteQuestion(id);
        return new ResponseEntity<>(questionResponse, HttpStatus.OK);
    }
}
