	if (ret < 0) {
		perror("read");
		exit(1);
	}

	for (i = 0; i < ret; i++) {
		if (buf[i] == '\n') {
			buf[i] = '\0';
			break;
		}
	}

	printf("%s\n", buf);

	free(buf);
	close(fd);

