#define BUF_SIZE 1024

int main(int argc, char *argv[])
{
	int fd;
	char *buf;
	int ret;
	pid_t pid;

	fd = open(argv[1], O_RDWR);
	if (fd < 0) {
		perror("open");
		exit(1);
	}

	buf = mmap(NULL, BUF_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
	if (buf == MAP_FAILED) {
		perror("mmap");
		exit(1);
	}

	pid = fork();
	if (pid < 0) {
		perror("fork");
		exit(1);
	}

	if (pid == 0) {
		ret = write(fd, "hello", 5);
		if (ret < 0) {
			perror("write");
			exit(1);
		}
	} else {
		ret = read(fd, buf, 5);
		if (ret < 0) {
			perror("read");
			exit(1);
		}
		printf("buf: %s\n", buf);
	}

	munmap(buf, BUF_SIZE);
	close(fd);

	return 0;
}
