#define BUF_SIZE 1024

int main(int argc, char *argv[])
{
	int fd;
	char *buf;
	int ret;

	if (argc!= 2) {
		printf("Usage: %s <file>\n", argv[0]);
		exit(1);
	}

	fd = open(argv[1], O_RDONLY);
	if (fd < 0) {
		perror("open");
		exit(1);
	}

	buf = mmap(NULL, BUF_SIZE, PROT_READ, MAP_PRIVATE, fd, 0);
	if (buf == MAP_FAILED) {
		perror("mmap");
		exit(1);
	}

	ret = strncmp(buf, "1", 1);
	if (ret == 0) {
		printf("1\n");
	} else if (ret == 1) {
		printf("0\n");
	} else {
		printf("not sure\n");
	}

	munmap(buf, BUF_SIZE);
	close(fd);

	return 0;
}
