#define PAGE_SIZE 4096

int main(int argc, char **argv)
{
	int fd;
	void *addr;
	int i;
	int sum = 0;

	fd = open("consolemap.c", O_RDONLY);
	if (fd < 0) {
		perror("open");
		exit(1);
	}

	addr = mmap(NULL, PAGE_SIZE, PROT_READ, MAP_PRIVATE, fd, 0);
	if (addr == MAP_FAILED) {
		perror("mmap");
		exit(1);
	}

	for (i = 0; i < PAGE_SIZE; i++) {
		if (addr[i] == 'p' && addr[i+1] == '1' && addr[i+2] == ']') {
			sum++;
		}
	}

	munmap(addr, PAGE_SIZE);
	close(fd);

	printf("%d\n", sum);

	return 0;
}
