			off = ptr_reg->smin_value + ptr_reg->off;
			*ptr_limit = ptr_reg->map_ptr->value_size - off - 1;
		}
		return *ptr_limit >= max? -ERANGE : 0;
	default:
		return -EINVAL;
	}
}

