	const char *d_name;
};

struct dentry_operations {
	int (*d_dname)(struct dentry *dentry, char *buffer, int buflen);
};

struct dentry *mount_pseudo(struct file_system_type *fs_type,
			    const char *name, void *data,
			    struct dentry_operations *d_op,
			    int magic)
{
	struct dentry *root = malloc(sizeof(struct dentry));
	root->d_parent = NULL;
	root->d_name = name;
	return root;
}

static int simple_dname(struct dentry *dentry, char *buffer, int buflen)
{
	int len = strlen(dentry->d_name);
	if (len >= buflen)
		return -ENAMETOOLONG;
	strcpy(buffer, dentry->d_name);
	return len;
}

static struct dentry *aio_mount(struct file_system_type *fs_type,
