	waitpid(pid, &status, 0);
	if (WIFEXITED(status)) {
		if (WEXITSTATUS(status) == 0)
			printf("1\n");
		else
			printf("0\n");
	} else {
		printf("not sure\n");
	}

	munmap(addr, PAGE_SIZE);
	close(fd);

	return 0;
}
