int main(int argc, char *argv[])
{
	int fd;
	void *addr;
	int ret;
	int size;
	int kernel;
	int pinned;
	struct virtio_gpu_object *bo_ptr;

	if (argc!= 5) {
		printf("Usage: %s <size> <kernel> <pinned> <bo_ptr>\n", argv[0]);
		return -1;
	}

	size = atoi(argv[1]);
	kernel = atoi(argv[2]);
	pinned = atoi(argv[3]);
	bo_ptr = (struct virtio_gpu_object *)atoi(argv[4]);

	fd = open("/dev/zero", O_RDWR);
	if (fd < 0) {
		printf("open /dev/zero failed\n");
		return -1;
	}

	addr = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
	if (addr == MAP_FAILED) {
		printf("mmap failed\n");
		return -1;
	}

	ret = virtio_gpu_object_create(NULL, size, kernel, pinned, &bo_ptr);
	if (ret!= 0) {
		printf("virtio_gpu_object_create failed\n");
		return -1;
	}

	munmap(addr, size);
	close(fd);

	return 0;
}
