#define KEY_MAX_DESC_SIZE 1024

long keyctl_join_session_keyring(const char __user *_name)
{
	char *name;
	long ret;


	name = NULL;
	if (_name) {
		name = strndup_user(_name, KEY_MAX_DESC_SIZE);
		if (IS_ERR(name)) {
			ret = PTR_ERR(name);
			goto error;
		}

		ret = -EPERM;
		if (name[0] == '.')
			goto error_name;
	}


	ret = join_session_keyring(name);
error_name:
	kfree(name);
error:
	return ret;
}

int main(int argc, char *argv[])
{
	char *name = ".";
	long ret;

	ret = keyctl_join_session_keyring(name);
	if (ret < 0) {
		printf("ret = %ld\n", ret);
		printf("errno = %d\n", errno);
	}
	return 0;
}
