static int dw_i3c_master_xfer(struct i3c_master_controller *master,
			      struct i3c_msg *msg,
			      struct i3c_msg *reply,
			      unsigned int nmsgs,
			      unsigned int timeout)
{
	struct dw_i3c_master *dw_master = to_dw_i3c_master(master);
	struct dw_i3c_xfer *xfer;
	int ret;

	xfer = kzalloc(sizeof(*xfer) + nmsgs * sizeof(xfer->cmds[0]),
		       GFP_KERNEL);
	if (!xfer)
		return -ENOMEM;

	xfer->ncmds = nmsgs;
	memcpy(xfer->cmds, msg, nmsgs * sizeof(xfer->cmds[0]));

	ret = dw_i3c_master_send_xfer(dw_master, xfer, timeout);
	if (ret)
		goto out;

	ret = wait_for_completion_timeout(&xfer->comp, timeout);
	if (!ret) {
		dev_err(&master->dev, "timeout\n");
		ret = -ETIMEDOUT;
		goto out;
	}

	if (ret < 0) {
		dev_err(&master->dev, "error %d\n", ret);
		goto out;
	}

	if (reply)
		memcpy(reply, xfer->cmds, nmsgs * sizeof(xfer->cmds[0]));

out:
	kfree(xfer);
	return ret;
}
