#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>

#define MAX_LINE_SIZE 1024

int main(int argc, char **argv)
{
	char line[MAX_LINE_SIZE];
	char *cwe_id;
	int fd;
	int i;
	int cwe_id_count = 0;
	char *cwe_ids[5];

	if (argc!= 2) {
		fprintf(stderr, "Usage: %s <file>\n", argv[0]);
		return 1;
	}

	fd = open(argv[1], O_RDONLY);
	if (fd < 0) {
		fprintf(stderr, "Failed to open file %s: %s\n", argv[1], strerror(errno));
		return 1;
	}

	while (fgets(line, MAX_LINE_SIZE, fd)!= NULL) {
		if (strncmp(line, "Code:", 5) == 0) {
			cwe_id = strstr(line, "CWE-");
			if (cwe_id) {
				cwe_ids[cwe_id_count] = strdup(cwe_id);
				cwe_id_count++;
			}
		}
	}

	printf("[");
	for (i = 0; i < cwe_id_count; i++) {
		if (i > 0)
			printf(", ");
		printf("\"%s\"", cwe_ids[i]);
	}
	printf("]\n");

	for (i = 0; i < cwe_id_count; i++)
		free(cwe_ids[i]);

	close(fd);

	return 0;
}
