	if (argc < 2) {
		printf("Usage: %s <cwe_list>\n", argv[0]);
		return 0;
	}

	for (i = 0; i < CWE_MAX_NUM; i++) {
		cwe_list[i] = NULL;
	}

	for (i = 0; i < strlen(argv[1]); i++) {
		if (argv[1][i] == ',') {
			cwe_list[cwe_num][i] = '\0';
			cwe_num++;
		} else {
			cwe_list[cwe_num][i] = argv[1][i];
		}
	}

	printf("[");
	for (i = 0; i < cwe_num; i++) {
		if (i!= 0)
			printf(", ");
		printf("\"CWE-%s\"", cwe_list[i]);
	}
	printf("]\n");

	return 0;
}
