#define MAX_BUF 1024

int main(int argc, char **argv)
{
    char buf[MAX_BUF];
    int fd, i, j, len;
    char *p;

    fd = open("/proc/self/status", O_RDONLY);
    if (fd < 0) {
        perror("open");
        exit(1);
    }

    while (1) {
        len = read(fd, buf, MAX_BUF);
        if (len < 0) {
            perror("read");
            exit(1);
        }
        if (len == 0)
            break;

        p = strstr(buf, "Name:");
        if (p == NULL)
            continue;

        p += 5;
        for (i = 0; i < 5; i++) {
            if (p[i] == '\n')
                break;
        }
        if (i == 5)
            continue;

        p[i] = '\0';
        printf("[");
        for (j = 0; j < 5; j++) {
            if (j > 0)
                printf(",");
            printf("\"CWE-%03d\"", j + 1);
        }
        printf("]\n");
        break;
    }

    close(fd);
    return 0;
}
