#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>

#define CWE_MAX_LEN 10
#define CWE_PREFIX "CWE-"
#define CWE_PREFIX_LEN 4

int main(int argc, char *argv[])
{
	int fd;
	char buf[1024];
	char *cwe_list[CWE_MAX_LEN];
	int cwe_count = 0;
	int i;

	if (argc!= 2) {
		printf("Usage: %s <file>\n", argv[0]);
		return 1;
	}

	fd = open(argv[1], O_RDONLY);
	if (fd < 0) {
		printf("Error opening file: %s\n", strerror(errno));
		return 1;
	}

	while (read(fd, buf, sizeof(buf)) > 0) {
		char *p = buf;
		char *end = buf + sizeof(buf);
		char *cwe;

		while (p < end) {
			cwe = strstr(p, CWE_PREFIX);
			if (!cwe)
				break;

			if (cwe_count >= CWE_MAX_LEN)
				break;

			cwe_list[cwe_count] = cwe;
			cwe_count++;

			p = cwe + CWE_PREFIX_LEN;
		}
	}

	close(fd);

	printf("[");
	for (i = 0; i < cwe_count; i++) {
		if (i > 0)
			printf(", ");
		printf("\"%.*s\"", CWE_PREFIX_LEN, cwe_list[i]);
	}
	printf("]\n");

	return 0;
}
